import type { Metadata } from "next";
import Link from "next/link";
import notices from "../../../lib/credits/notices.json";

export const metadata: Metadata = {
  title: "Open-source notices · Pneuma Mundi",
  description: "Every open-source package that ships in Pneuma Mundi, with its licence text.",
  alternates: { canonical: "/credits/open-source" },
};

/** Generated by scripts/gen-notices.mjs from the lockfile (web bundle + Capacitor iOS shell). */
export default function OpenSourcePage() {
  return (
    <main
      style={{
        maxWidth: 680,
        margin: "0 auto",
        padding: "max(2.5rem, env(safe-area-inset-top)) 1.25rem calc(3rem + env(safe-area-inset-bottom))",
        color: "#b9b5cc",
        lineHeight: 1.6,
        fontSize: "0.95rem",
      }}
    >
      <p style={{ letterSpacing: "0.2em", fontSize: "0.7rem", textTransform: "uppercase" }}>Pneuma Mundi</p>
      <h1 style={{ fontSize: "1.6rem", color: "#f4f1ff", fontWeight: 400, margin: "0.25rem 0 0" }}>Open-source notices</h1>
      <p>
        {notices.length} packages ship in the app and on this site, including the Capacitor iOS shell. Tap one for its
        licence. Thank you to everyone who made them.
      </p>
      <p>
        <Link href="/credits">← Credits &amp; data</Link>
      </p>
      {notices.map((n) => (
        <details key={`${n.name}@${n.version}`} style={{ borderTop: "1px solid rgba(255,255,255,0.08)", padding: "0.5rem 0" }}>
          <summary style={{ cursor: "pointer", color: "#e8e4f4" }}>
            {n.name} {n.version} <span style={{ color: "#8f8aa6" }}>· {n.license}</span>
          </summary>
          {n.url ? (
            <p style={{ fontSize: "0.8rem", wordBreak: "break-all" }}>
              <a href={n.url} target="_blank" rel="noopener noreferrer">
                {n.url}
              </a>
            </p>
          ) : null}
          <pre style={{ whiteSpace: "pre-wrap", fontSize: "0.72rem", lineHeight: 1.45, color: "#a6a1bb" }}>{n.text}</pre>
        </details>
      ))}
      <p style={{ marginTop: "2.5rem" }}>
        <Link href="/credits">← Credits &amp; data</Link> · <Link href="/">Pneuma Mundi</Link>
      </p>
    </main>
  );
}
